with parsed as (select id, host, log_ts, payload_json, context, context['version'] as version, array_contains(map_keys(context), 'trace') as has_trace, get_json_object(payload_json, '$.user.id') as user_id from app_logs where host = 'h4') select id, host, log_ts, version, user_id, first_value(version, true) over (partition by host order by log_ts, id rows between unbounded preceding and current row) as first_known_version, first_value(version, true) over (partition by host order by log_ts, id rows between unbounded preceding and current row) as first_known_version_2, row_number() over (partition by month(log_ts), host order by log_ts, id) as row_seq, row_number() over (partition by year(log_ts), host order by log_ts, id) as event_seq from parsed where not has_trace
